package dev.pixelair.launcher;
import android.app.*;
import android.appwidget.*;
import android.graphics.Color;
import android.graphics.drawable.Drawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.function.*;

/** Visual pickers recycle cells and retain ordinary platform widget binding/configuration. */
final class LauncherEditors {
 static int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}
 static TextView text(Activity a,String label,int size){TextView v=new TextView(a);v.setText(label);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);return v;}
 static LinearLayout column(Activity a){LinearLayout v=new LinearLayout(a);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(a,12),dp(a,8),dp(a,12),dp(a,8));return v;}
 static void apps(Activity a,String title,List<HomeActivity.App> apps,Function<HomeActivity.App,Drawable> icon,Consumer<HomeActivity.App> choose,Runnable reset){
  LinearLayout content=column(a);EditText search=new EditText(a);search.setSingleLine();search.setHint(a.getString(R.string.ui_131));content.addView(search);GridView grid=new GridView(a);grid.setNumColumns(4);grid.setVerticalSpacing(dp(a,8));content.addView(grid,new LinearLayout.LayoutParams(-1,dp(a,380)));ArrayList<HomeActivity.App> visible=new ArrayList<>(apps);
  BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){LinearLayout cell=old instanceof LinearLayout?(LinearLayout)old:column(a);if(cell.getChildCount()==0){ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.FIT_CENTER);cell.addView(image,new LinearLayout.LayoutParams(-1,dp(a,52)));TextView label=text(a,"",11);label.setMaxLines(2);cell.addView(label,new LinearLayout.LayoutParams(-1,dp(a,36)));}HomeActivity.App app=visible.get(n);((ImageView)cell.getChildAt(0)).setImageDrawable(icon.apply(app));((TextView)cell.getChildAt(1)).setText(app.label);cell.setContentDescription(app.label);return cell;}};grid.setAdapter(adapter);
  AlertDialog.Builder builder=new AlertDialog.Builder(a).setTitle(title).setView(content).setNegativeButton(a.getString(R.string.ui_035),null);if(reset!=null)builder.setNeutralButton(a.getString(R.string.ui_132),(d,w)->reset.run());AlertDialog dialog=builder.create();grid.setOnItemClickListener((p,v,n,id)->{choose.accept(visible.get(n));dialog.dismiss();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){visible.clear();String q=s.toString().toLowerCase(Locale.ROOT);for(HomeActivity.App app:apps)if(app.label.toLowerCase(Locale.ROOT).contains(q))visible.add(app);adapter.notifyDataSetChanged();}});dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
 }
 static void widgets(Activity a,List<AppWidgetProviderInfo> installed,Consumer<AppWidgetProviderInfo> choose){
  ArrayList<AppWidgetProviderInfo> providers=new ArrayList<>(installed);providers.sort((x,y)->x.loadLabel(a.getPackageManager()).compareToIgnoreCase(y.loadLabel(a.getPackageManager())));
  if(providers.isEmpty()){Toast.makeText(a,a.getString(R.string.ui_133),Toast.LENGTH_SHORT).show();return;}
  LinearLayout content=column(a);TextView hint=text(a,a.getString(a.getSharedPreferences("home",0).getInt("widget",-1)==-1?R.string.ui_134:R.string.widget_replace_hint),13);content.addView(hint);EditText search=new EditText(a);search.setSingleLine();search.setHint(a.getString(R.string.ui_135));content.addView(search);ListView list=new ListView(a);content.addView(list,new LinearLayout.LayoutParams(-1,dp(a,420)));ArrayList<AppWidgetProviderInfo> visible=new ArrayList<>(providers);
  BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){LinearLayout card=old instanceof LinearLayout?(LinearLayout)old:column(a);if(card.getChildCount()==0){card.addView(text(a,"",16));ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(image,new LinearLayout.LayoutParams(-1,dp(a,108)));card.addView(text(a,"",12));}AppWidgetProviderInfo info=visible.get(n);String label=info.loadLabel(a.getPackageManager());((TextView)card.getChildAt(0)).setText(label);Drawable preview=null;try{preview=info.loadPreviewImage(a,a.getResources().getDisplayMetrics().densityDpi);}catch(RuntimeException ignored){}boolean actual=preview!=null;if(preview==null)preview=info.loadIcon(a,a.getResources().getDisplayMetrics().densityDpi);((ImageView)card.getChildAt(1)).setImageDrawable(preview);((TextView)card.getChildAt(2)).setText((actual?a.getString(R.string.ui_136):a.getString(R.string.ui_137))+" · "+Math.max(1,Math.round(info.minWidth/a.getResources().getDisplayMetrics().density))+a.getString(R.string.ui_138)+Math.max(1,Math.round(info.minHeight/a.getResources().getDisplayMetrics().density))+" dp");card.setContentDescription(a.getString(R.string.ui_139)+label);return card;}};list.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Widget").setView(content).setNegativeButton(a.getString(R.string.ui_035),null).create();list.setOnItemClickListener((p,v,n,id)->{AppWidgetProviderInfo info=visible.get(n);dialog.dismiss();choose.accept(info);});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){visible.clear();String q=s.toString().toLowerCase(Locale.ROOT);for(AppWidgetProviderInfo info:providers)if(info.loadLabel(a.getPackageManager()).toLowerCase(Locale.ROOT).contains(q))visible.add(info);adapter.notifyDataSetChanged();}});dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
 }
}
